48: export function setCookie(name: string, val: string) {
49:   const date = new Date();
50:   date.setTime(date.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 días
51:   document.cookie = `${name}=${val}; expires=${date.toUTCString()}; path=/`;
52: }
53: 
54: export function getCookie(name: string): string | undefined {
55:   const value = '; ' + document.cookie;
56:   const parts = value.split('; ' + name + '=');
57:   if (parts.length == 2) {
58:     return parts.pop()?.split(';').shift();
59:   }
60:   return undefined;
61: }

